import{COLORS}from'../../../assets/core.mjs';import{auditRows,intersection,describeError02}from'../../../assets/legality02.mjs';
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const text=(x,y,s,size=22,color='#254c42',anchor='middle')=>`<text x="${x}" y="${y}" font-size="${size}" fill="${color}" text-anchor="${anchor}">${esc(s)}</text>`;
const rect=(x,y,w,h,fill,stroke='#b4c6b5',extra='')=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="2" fill="${fill}" stroke="${stroke}" ${extra}/>`;
export function board(rows,outline=[10,8],opts={}){const{x=100,y=95,w=760,h=350,corners=false,interactive=true,showPairs=true,focus=[]}=opts,u=Math.min(w/outline[0],h/outline[1]),ox=x+(w-outline[0]*u)/2,oy=y+(h-outline[1]*u)/2;let s=`<g data-board="true" data-unit="${u}">`+rect(ox,oy,outline[0]*u,outline[1]*u,'#f7faf2','#8caa95');
 for(let i=1;i<outline[0];i++)s+=`<path d="M${ox+i*u} ${oy}v${outline[1]*u}" stroke="#dce6d8"/>`;for(let i=1;i<outline[1];i++)s+=`<path d="M${ox} ${oy+i*u}h${outline[0]*u}" stroke="#dce6d8"/>`;
 const valid=rows.map((r,i)=>({r,i})).filter(({r})=>r.slice(1).every(Number.isFinite)&&r[3]>0&&r[4]>0);
 for(const{r:[id,X,Y,W,H],i}of valid){const px=ox+X*u,py=oy+(outline[1]-Y-H)*u,color=COLORS[id]||(['#437ba5','#c08a42'][i%2]);s+=`<g ${interactive?`data-row="${i}" role="button" tabindex="0" aria-label="模块 ${esc(id)}，第${i+1}行"`:''} opacity="${focus.length&&!focus.includes(id)?.45:1}">`+rect(px,py,W*u,H*u,color,'#fff');if(W*u>=25&&H*u>=20)s+=text(px+W*u/2,py+H*u/2+4,id,Math.min(25,u*.7),'#fff');if(W*u>=55&&H*u>=50)s+=text(px+W*u/2,py+H*u/2+24,W+'×'+H,14,'#fff');if(corners)for(const[a,b]of[[0,0],[W,0],[0,H],[W,H]])s+=`<circle cx="${px+a*u}" cy="${py+b*u}" r="4" fill="#fff" stroke="#853c2c"/>`;s+='</g>';}
 if(showPairs)for(let i=0;i<rows.length;i++)for(let j=i+1;j<rows.length;j++){if(!valid.some(a=>a.i===i)||!valid.some(a=>a.i===j))continue;const v=intersection(rows[i],rows[j]);if(v.area>0)s+=rect(ox+Math.max(rows[i][1],rows[j][1])*u,oy+(outline[1]-Math.min(rows[i][2]+rows[i][4],rows[j][2]+rows[j][4]))*u,v.dx*u,v.dy*u,'url(#collision)','#a34231','pointer-events="none"');}
 s+=text(ox,oy+outline[1]*u+22,'0',15,'#678270')+text(ox+outline[0]*u,oy+outline[1]*u+22,String(outline[0]),15,'#678270')+text(ox-16,oy+7,String(outline[1]),15,'#678270')+text(ox+outline[0]*u/2,oy-14,'外框 '+outline[0]+'×'+outline[1],17);return s+'</g>';}
const cards=(items,p)=>items.map(([h,b],i)=>{const x=55+(i%2)*455,y=110+Math.floor(i/2)*155;return rect(x,y,415,130,'#edf3e8',p*items.length>=i?'#72997e':'#c8d4c6')+text(x+20,y+38,h,25,'#234e40','start')+text(x+20,y+85,b,19,'#58796a','start');}).join('');
export function renderScene(scene,time,trial,reduced){const p=Math.max(0,Math.min(1,(time-scene.start)/(scene.end-scene.start))),o=scene.outline||[10,8];let rows=trial||scene.rows,body='';
 if(!trial&&scene.from){const q=reduced?1:Math.max(0,Math.min(1,(time-scene.start-1)/2.7)),e=q*q*(3-2*q);rows=scene.rows.map((r,i)=>r.map((v,j)=>j===1||j===2?scene.from[i][j]+(v-scene.from[i][j])*e:v));}
 if(trial||scene.view==='board')body=board(rows,o,{focus:trial?[]:scene.focus||[],showPairs:!!trial||!scene.question});
 else if(scene.view==='intro-flow'){
  body+=rect(40,140,255,115,'#edf3e8','#72997e')+text(167,182,'输入',25,'#234e40')+text(167,220,'模块清单 + 固定外框',18,'#58796a');
  body+='<path d="M295 197h45" stroke="#72997e" stroke-width="2"/><path d="M340 197l-10-6v12z" fill="#72997e"/>';
  body+=rect(340,140,255,115,'#edf3e8','#72997e')+text(467,182,'自动摆放',25,'#234e40')+text(467,220,'算法摆放，人工微调',18,'#58796a');
  body+='<path d="M595 197h45" stroke="#72997e" stroke-width="2"/><path d="M640 197l-10-6v12z" fill="#72997e"/>';
  body+=rect(640,140,280,115,'#edf3e8','#72997e')+text(780,182,'一份坐标',25,'#234e40')+text(780,220,'每块 (x, y, 宽, 高)',18,'#58796a');
  body+='<path d="M780 255v20H480v37" fill="none" stroke="#72997e" stroke-width="2"/><path d="M480 314l-6-10h12z" fill="#72997e"/>';
  body+=rect(280,315,400,95,p>.55?'#f6ead9':'#f3f6ef','#c9a06d')+text(480,353,'下一步：压紧与评分',26,'#8a5a26')+text(480,388,'但如果布局本身用不了，分数就没有意义',19,'#a04e36');
 }
 else if(scene.view==='intro-goal')body=cards([['输入','任意一组矩形、外框和模块清单'],['输出','全部错误，并指出具体位置'],['不做什么','不优化、不重摆；只判断能否使用'],['为什么重要','评分、解码、搜索都默认它先通过']],p);
 else if(scene.view==='contract')body=cards([['每块恰好出现一次','A、B、C、D、E，不能重复或漏放'],['尺寸按清单固定','A3×2、B2×3、C/E2×2、D3×1'],['每条边都在框内','10×8外框；坐标从左下角开始'],['不能占同一片内部空间','允许共边、共角；这次禁止旋转']],p);
 else if(scene.view==='numbers')body=cards([['3×2','正尺寸，还要对照模块清单'],['3×0','高度为0，不能当成矩形'],['−3×−2','乘积虽为正，尺寸仍不允许'],['坐标为NaN或∞','不是可使用的有限坐标']],p);
 else if(scene.view==='bounds'){body=board(rows,o,{x:35,y:115,w:525,h:305,focus:['E']});['x ≥ 0','y ≥ 0','x + w ≤ W','y + h ≤ H'].forEach((s,i)=>body+=text(730,150+i*76,s,28,p*4>=i?'#905b33':'#93a391'));}
 else if(scene.view.startsWith('projection')){body=board(rows,o,{x:35,y:100,w:470,h:320,focus:['C','E']});const X=565,Y=185,unit=43,ys=scene.view==='projection-y';body+=text(735,130,ys?'纵向的共同部分':'横向的共同部分',25);const ranges=ys?[[0,2],[0,2]]:[[5,7],[6,8]],min=ys?0:4;for(let i=0;i<2;i++){const[a,b]=ranges[i];body+=rect(X+(a-min)*unit,Y+i*80,(b-a)*unit,24,i?'#bb7589':'#c08a42')+text(735,Y+i*80+58,(i?'E':'C')+`：[${a},${b}]`,21);}if(p>.3)body+=text(735,402,ys?'共同高2；面积1×2=2':'共同区间[6,7]，宽1',23,'#a04e36');}
 else if(scene.view==='formula'){body=text(480,140,'共同宽 dx = max(0, min(x₁+w₁, x₂+w₂) − max(x₁,x₂))',26);if(p>.25)body+=text(480,220,'共同高 dy = max(0, min(y₁+h₁, y₂+h₂) − max(y₁,y₂))',26);if(p>.5)body+=text(480,310,'重叠面积 = dx × dy',32,'#9a5c31');if(p>.7)body+=text(480,405,'dx > 0 且 dy > 0，才是正面积重叠',26);}
 else if(scene.view==='contacts'){const layouts=[[['P',0,0,2,2],['Q',2,0,2,2]],[['P',0,0,2,2],['Q',2,2,2,2]],[['P',0,0,2,2],['Q',1,1,2,2]]];layouts.forEach((r,i)=>{body+=board(r,[4,4],{x:30+i*310,y:160,w:280,h:230,interactive:false});body+=text(170+i*310,440,['共边：面积0','共角：面积0','内部重叠：面积1'][i],23,i===2?'#a04430':'#35664c');});}
 else if(scene.view==='contained'||scene.view==='cross')body=board(rows,o,{x:120,y:105,w:720,h:335,corners:scene.view==='cross'});
 else if(scene.view==='identity'){body=text(480,120,'模块清单：A、B、C、D、E',26);rows.forEach((r,i)=>{const x=65+i*175;body+=rect(x,170,150,130,'#edf3e8')+text(x+75,222,r[0],35)+text(x+75,269,r[3]+'×'+r[4],22);});if(p>.35)body+=text(480,365,'五行数据，但A重复、B缺失',29,'#a04e36');if(p>.65)body+=text(480,425,'第二行的A还是2×3，不符合A固定3×2',23);}
 else if(scene.view==='algorithm'||scene.view==='pipeline'){const lines=scene.view==='pipeline'?['读取新的rows、outline和catalog','逐行核对名称、数值、固定尺寸和边界','遍历所有模块对，计算共同宽和高','返回全部定位错误和真实交集面积']:['核对名称：缺失、重复、未知','排除无效数值，再检查固定尺寸','检查每块四条边是否在外框内','检查全部模块对：5块共有10对','返回错误清单；没有错误才合法'];lines.forEach((s,i)=>{const y=105+i*72;body+=rect(65,y,830,57,p*lines.length>=i?'#e2eddf':'#f3f6ef')+text(90,y+38,`${i+1}. ${s}`,25,'#315b49','start');});}
 else if(scene.view==='capacity'){body=board(scene.rows,[4,4],{x:90,y:150,w:390,h:270,interactive:false})+text(700,180,'3×2 + 2×3 = 12',29)+text(700,250,'外框4×4 = 16',29)+text(700,340,'12 < 16，面积够',27,'#35664c')+text(700,405,'形状真的放得下吗？',25,'#a04e36');}
 else if(scene.view==='separation'){const horiz=[['A',0,0,3,2],['B',3,0,2,3]],vert=[['A',0,0,3,2],['B',0,2,2,3]];body=board(horiz,[4,4],{x:40,y:145,w:360,h:245,interactive:false})+board(vert,[4,4],{x:550,y:145,w:360,h:245,interactive:false});body+=text(235,442,'左右分开：至少宽5 > 4',25,'#a04e36')+text(730,442,'上下分开：至少高5 > 4',25,'#a04e36');}
 return`<defs><pattern id="collision" width="8" height="8" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><rect width="8" height="8" fill="#efc2ad"/><path d="M0 0V8" stroke="#a74330" stroke-width="3"/></pattern></defs>${text(35,44,trial?'自己的尝试':scene.title,28,'#1c3a31','start')}${text(925,44,'第 '+scene.chapter+' / 8 章',13,'#6b8373','end')}${body}${text(480,512,trial?'每次改完，都检查一下发生了什么变化':scene.note,18)}`;
}
export function reportTrial(rows,scene){const r=auditRows(rows,scene.outline||[10,8],scene.catalog);return r.legal?'当前摆放符合这一步的模块清单和几何规则。':'当前问题：'+r.errors.map(describeError02).join('，')+(r.pairs.length?'；交集面积：'+r.pairs.map(p=>p.ids.join('/')+'='+p.area).join('，'):'');}
